def transform(grid):
    out = [row[:] for row in grid]
    for row in out:
        if len(set(row)) > 1:
            first = row[0]
            boundary = next((i for i, value in enumerate(row) if value != first), len(row))
            row[boundary:] = [1] * (len(row) - boundary)
    return out
